negativeExample:
package test;

import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;

// Mock classes for compilation context
class JavaCore { public static final String PLUGIN_ID = "org.eclipse.jdt.core"; }
class JavaPlugin { public static void log(IStatus status) { System.err.println(status.getMessage()); } }

public class NegativeExample {
    public void testMethod() {
        Throwable ex = new Exception("Custom message for negative test.");

        // Should not match: message is a literal string, not from ex.getMessage()
        JavaPlugin.log(new Status(
                IStatus.ERROR,
                JavaCore.PLUGIN_ID,
                "A specific literal message",
                ex));

        // Should not match: already using the simplified constructor
        JavaPlugin.log(new Status(
                IStatus.ERROR,
                JavaCore.PLUGIN_ID,
                ex));

        // Should not match: different constructor signature
        JavaPlugin.log(new Status(
                IStatus.WARNING,
                JavaCore.PLUGIN_ID,
                "Just a message"));
    }
}
